/** Artwork is derived only from the user-supplied reference image, stored compactly for the overlay. */
public final class CatArt {
    private CatArt(){}
    private static final String A="";
    private static final String B="";
    private static final String C="";
    private static final String D="D8dm6bFRcXzuU1SZuShFhDGDxdune/Ku8Lr+6YWG2t10zEJGiWoRobgCCATI+L5HV0on9lCOzuy6AAAA";
    public static Bitmap decode(){ byte[] b=Base64.decode(A+B+C+D,Base64.DEFAULT); return BitmapFactory.decodeByteArray(b,0,b.length); }
}
